func lengthOfLongestSubstring(s string) int {
    pos := make(map[byte]int)
    best, left := 0, 0
    for right := 0; right < len(s); right++ {
        c := s[right]
        if p, ok := pos[c]; ok && p >= left {
            left = p + 1 // 跳过重复字符
        }
        pos[c] = right
        if right-left+1 > best {
            best = right - left + 1
        }
    }
    return best
}
